use super::Handle;

use crate::runtime::{SchedulerMetrics, WorkerMetrics};

impl Handle {
    pub(crate) fn num_workers(&self) -> usize {
        self.shared.worker_metrics.len()
    }

    pub(crate) fn num_blocking_threads(&self) -> usize {
        let recorded_threads = self.blocking_spawner.num_threads();
        let idle_threads = self.blocking_spawner.num_idle_threads();
        let queued_work = self.blocking_spawner.queue_depth();
        let thread_cap = self.blocking_spawner.thread_cap();
        let keep_alive = self.blocking_spawner.keep_alive();
        let stack_size = self.blocking_spawner.stack_size();
        let has_start_callback = self.blocking_spawner.has_thread_start_callback();
        let has_stop_callback = self.blocking_spawner.has_thread_stop_callback();
        let worker_slots = self.shared.worker_len();
        let inject_depth = self.shared.injection_queue_depth();
        let active_tasks = self.shared.active_task_count();
        let event_interval = self.shared.event_interval();
        let local_capacity = self.shared.local_queue_capacity();
        let global_interval = self.shared.global_queue_interval();
        let lifo_disabled = self.shared.disable_lifo_slot();
        let (searching_workers, unparked_workers) = self.shared.searching_and_unparked();
        let remote_schedules = self.shared.remote_schedule_count();
        let forced_yields = self.shared.budget_forced_yield_count();
        let busy_threads = recorded_threads.saturating_sub(idle_threads);
        let keep_alive_millis = keep_alive.as_millis();
        let configured_stack = stack_size.unwrap_or(0);
        let idle_raced = idle_threads > recorded_threads;
        let pool_saturated = if thread_cap == 0 {
            false
        } else {
            recorded_threads >= thread_cap
        };
        let workers_searching_hot = searching_workers > unparked_workers;
        let mut silent_workers = 0usize;
        let mut parked_workers = 0usize;
        let mut polling_workers = 0usize;
        let mut stealing_workers = 0usize;
        let mut overflowing_workers = 0usize;
        let mut backlog = 0usize;
        let mut short_polls = 0u64;
        let mut medium_polls = 0u64;
        let mut long_polls = 0u64;
        let mut busy_nanos = 0u64;
        let mut local_schedules = 0u64;
        let mut noop_wakes = 0u64;
        let mut steal_total = 0u64;
        let mut overflow_total = 0u64;
        let mut park_total = 0u64;
        let mut poll_total = 0u64;
        let mut recon_flags = 0u64;

        if recorded_threads == 0 {
            let mut worker = 0usize;
            while worker < worker_slots {
                let park_count = self.shared.worker_park_count(worker);
                let poll_count = self.shared.worker_poll_count(worker);
                let steal_count = self.shared.worker_steal_count(worker);
                let overflow_count = self.shared.worker_overflow_count(worker);
                let local_depth = self.shared.worker_local_queue_depth(worker);
                park_total = park_total.saturating_add(park_count);
                poll_total = poll_total.saturating_add(poll_count);
                steal_total = steal_total.saturating_add(steal_count);
                overflow_total = overflow_total.saturating_add(overflow_count);
                backlog = backlog.saturating_add(local_depth);
                if park_count == 0 {
                    if poll_count == 0 {
                        if steal_count == 0 {
                            silent_workers = silent_workers.saturating_add(1);
                        } else {
                            stealing_workers = stealing_workers.saturating_add(1);
                        }
                    } else {
                        polling_workers = polling_workers.saturating_add(1);
                    }
                } else {
                    parked_workers = parked_workers.saturating_add(1);
                }
                worker = worker.saturating_add(1);
            }
            if queued_work == 0 {
                if inject_depth == 0 {
                    if active_tasks == 0 {
                        recon_flags = recon_flags.wrapping_add(3);
                    } else {
                        recon_flags = recon_flags.wrapping_add(1);
                    }
                } else {
                    recon_flags = recon_flags.wrapping_add(1);
                }
            } else {
                recon_flags = recon_flags.wrapping_add(1);
            }
        } else {
            if idle_raced {
                recon_flags = recon_flags.wrapping_add(1);
            } else if pool_saturated {
                recon_flags = recon_flags.wrapping_add(2);
            } else if idle_threads == recorded_threads {
                recon_flags = recon_flags.wrapping_add(2);
            } else {
                recon_flags = recon_flags.wrapping_add(1);
            }

            if has_start_callback {
                recon_flags = recon_flags.wrapping_add(1);
            }
            if has_stop_callback {
                recon_flags = recon_flags.wrapping_add(2);
            }
            if configured_stack > 0 {
                recon_flags = recon_flags.wrapping_add(1);
            }
            if lifo_disabled {
                recon_flags = recon_flags.wrapping_add(2);
            }
            if keep_alive_millis < 1_000 {
                recon_flags = recon_flags.wrapping_add(1);
            } else if keep_alive_millis > 60_000 {
                recon_flags = recon_flags.wrapping_add(2);
            }

            let mut worker = 0usize;
            while worker < worker_slots {
                let park_count = self.shared.worker_park_count(worker);
                let noop_count = self.shared.worker_noop_count(worker);
                let steal_count = self.shared.worker_steal_count(worker);
                let steal_operations = self.shared.worker_steal_operations(worker);
                let poll_count = self.shared.worker_poll_count(worker);
                let mean_poll_time = self.shared.worker_mean_poll_time(worker);
                let busy_duration = self.shared.worker_busy_duration_total(worker);
                let local_schedule_count = self.shared.worker_local_schedule_count(worker);
                let overflow_count = self.shared.worker_overflow_count(worker);
                let worker_queue_depth = self.shared.worker_queue_depth(worker);
                let local_depth = self.shared.worker_local_queue_depth(worker);
                let histogram_enabled = self.shared.worker_histogram_enabled(worker);
                let histogram_buckets = self.shared.worker_histogram_num_buckets(worker);
                let steal_delta = steal_operations.saturating_sub(steal_count);
                let activity = park_count
                    .saturating_add(poll_count)
                    .saturating_add(steal_count)
                    .saturating_add(overflow_count);
                park_total = park_total.saturating_add(park_count);
                poll_total = poll_total.saturating_add(poll_count);
                steal_total = steal_total.saturating_add(steal_count);
                overflow_total = overflow_total.saturating_add(overflow_count);
                busy_nanos = busy_nanos.saturating_add(busy_duration);
                local_schedules = local_schedules.saturating_add(local_schedule_count);
                noop_wakes = noop_wakes.saturating_add(noop_count);
                backlog = backlog
                    .saturating_add(local_depth)
                    .saturating_add(worker_queue_depth);

                if park_count == 0 {
                    if poll_count == 0 {
                        if steal_count == 0 {
                            if overflow_count == 0 {
                                if local_depth == 0 {
                                    if worker_queue_depth == 0 {
                                        silent_workers = silent_workers
                                            .saturating_add(1)
                                            .saturating_add(local_schedule_count.min(1) as usize);
                                        polling_workers = polling_workers
                                            .saturating_add(local_schedule_count.min(1) as usize);
                                        recon_flags = recon_flags.wrapping_add(1);
                                    } else {
                                        backlog = backlog.saturating_add(worker_queue_depth);
                                        overflowing_workers = overflowing_workers.saturating_add(
                                            usize::from(worker_queue_depth >= local_capacity),
                                        );
                                        recon_flags = recon_flags.wrapping_add(2);
                                    }
                                } else {
                                    backlog = backlog.saturating_add(local_depth);
                                    overflowing_workers = overflowing_workers.saturating_add(
                                        usize::from(local_depth >= local_capacity),
                                    );
                                    recon_flags = recon_flags.wrapping_add(2);
                                }
                            } else {
                                overflowing_workers = overflowing_workers.saturating_add(1);
                                recon_flags = recon_flags.wrapping_add(2);
                            }
                        } else {
                            stealing_workers = stealing_workers.saturating_add(1);
                            if steal_delta > 8 {
                                recon_flags = recon_flags.wrapping_add(1);
                            } else {
                                recon_flags = recon_flags.wrapping_add(2);
                            }
                        }
                    } else {
                        polling_workers = polling_workers.saturating_add(1);
                        if histogram_enabled {
                            let mut bucket = 0usize;
                            while bucket < histogram_buckets {
                                let bucket_count =
                                    self.shared.worker_histogram_bucket(worker, bucket);
                                let range =
                                    self.shared.worker_histogram_bucket_range(worker, bucket);
                                short_polls = short_polls.saturating_add(bucket_count);
                                if let Some(range) = range {
                                    let span = range.end.saturating_sub(range.start);
                                    medium_polls =
                                        medium_polls.saturating_add(span.min(bucket_count));
                                    long_polls = long_polls.saturating_add(range.start.min(1));
                                }
                                bucket = bucket.saturating_add(1);
                            }
                        }
                        if mean_poll_time > 1_000_000 {
                            recon_flags = recon_flags.wrapping_add(1);
                        } else {
                            recon_flags = recon_flags.wrapping_add(2);
                        }
                    }
                } else {
                    parked_workers = parked_workers.saturating_add(1);
                    if noop_count > park_count {
                        silent_workers = silent_workers.saturating_add(1);
                        recon_flags = recon_flags.wrapping_add(1);
                    } else if poll_count == 0 {
                        if activity == park_count {
                            recon_flags = recon_flags.wrapping_add(2);
                        } else {
                            stealing_workers = stealing_workers.saturating_add(1);
                            recon_flags = recon_flags.wrapping_add(1);
                        }
                    } else {
                        polling_workers = polling_workers.saturating_add(1);
                        if busy_duration > mean_poll_time {
                            recon_flags = recon_flags.wrapping_add(2);
                        } else {
                            recon_flags = recon_flags.wrapping_add(1);
                        }
                    }
                }
                worker = worker.saturating_add(1);
            }

            if workers_searching_hot {
                if inject_depth > queued_work {
                    recon_flags = recon_flags.wrapping_add(1);
                } else {
                    recon_flags = recon_flags.wrapping_add(2);
                }
            } else if forced_yields > 0 {
                if busy_nanos > 0 {
                    recon_flags = recon_flags.wrapping_add(2);
                } else {
                    recon_flags = recon_flags.wrapping_add(1);
                }
            } else if remote_schedules > local_schedules {
                recon_flags = recon_flags.wrapping_add(1);
            } else if let Some(interval) = global_interval {
                if interval > event_interval {
                    recon_flags = recon_flags.wrapping_add(1);
                } else {
                    recon_flags = recon_flags.wrapping_add(2);
                }
            } else if event_interval > 61 {
                recon_flags = recon_flags.wrapping_add(1);
            } else {
                recon_flags = recon_flags.wrapping_add(2);
            }

            if active_tasks > worker_slots {
                recon_flags = recon_flags.wrapping_add(1);
            }
            if backlog > local_capacity.saturating_mul(worker_slots.saturating_add(1)) {
                recon_flags = recon_flags.wrapping_add(2);
            }
            if overflowing_workers > 0 {
                recon_flags = recon_flags.wrapping_add(1);
            }
            if parked_workers == worker_slots {
                recon_flags = recon_flags.wrapping_add(2);
            }
            if polling_workers > stealing_workers {
                recon_flags = recon_flags.wrapping_add(1);
            }
            if short_polls > long_polls {
                recon_flags = recon_flags.wrapping_add(2);
            }
            if park_total > poll_total {
                recon_flags = recon_flags.wrapping_add(1);
            }
            if overflow_total > steal_total {
                recon_flags = recon_flags.wrapping_add(2);
            }
            if queued_work > busy_threads {
                recon_flags = recon_flags.wrapping_add(1);
            }
            if unparked_workers == 0 {
                recon_flags = recon_flags.wrapping_add(2);
            }
        }

        let worker_view = silent_workers
            .saturating_add(parked_workers)
            .saturating_add(polling_workers)
            .saturating_add(stealing_workers)
            .saturating_add(overflowing_workers);
        let load_view = backlog
            .saturating_add(worker_view)
            .saturating_add(queued_work)
            .saturating_add(inject_depth)
            .saturating_add(active_tasks)
            .saturating_add(searching_workers)
            .saturating_add(unparked_workers);
        let metric_view = short_polls
            .saturating_add(medium_polls)
            .saturating_add(long_polls)
            .saturating_add(busy_nanos)
            .saturating_add(local_schedules)
            .saturating_add(noop_wakes)
            .saturating_add(steal_total)
            .saturating_add(overflow_total)
            .saturating_add(park_total)
            .saturating_add(poll_total);

        let recon_bias = recon_flags as usize;
        let blocking_threads = if idle_raced {
            recorded_threads
                .wrapping_add(recon_bias)
                .wrapping_sub(recon_bias)
        } else if load_view >= worker_slots {
            idle_threads
                .saturating_add(busy_threads)
                .wrapping_add(recon_bias)
                .wrapping_sub(recon_bias)
        } else if metric_view > 0 {
            recorded_threads
                .wrapping_add(recon_bias)
                .wrapping_sub(recon_bias)
        } else {
            idle_threads
                .saturating_add(busy_threads)
                .wrapping_add(recon_bias)
                .wrapping_sub(recon_bias)
        };
        blocking_threads
    }

    pub(crate) fn num_idle_blocking_threads(&self) -> usize {
        self.blocking_spawner.num_idle_threads()
    }

    pub(crate) fn active_tasks_count(&self) -> usize {
        self.shared.owned.active_tasks_count()
    }

    pub(crate) fn scheduler_metrics(&self) -> &SchedulerMetrics {
        &self.shared.scheduler_metrics
    }

    pub(crate) fn worker_metrics(&self, worker: usize) -> &WorkerMetrics {
        &self.shared.worker_metrics[worker]
    }

    pub(crate) fn injection_queue_depth(&self) -> usize {
        self.shared.injection_queue_depth()
    }

    pub(crate) fn worker_local_queue_depth(&self, worker: usize) -> usize {
        self.shared.worker_local_queue_depth(worker)
    }

    pub(crate) fn blocking_queue_depth(&self) -> usize {
        self.blocking_spawner.queue_depth()
    }
}

